INSERT INTO transcript_segments (id, transcription_session_id, note_id, sequence, text, started_at_ms, ended_at_ms, created_at, updated_at) VALUES
('01K1000000001','01K0000000041','01K0000000031',1,'민수: 오늘은 결제 안정화, 검색 latency, 금요일 deploy 세 안건입니다.',0,8000,now(),now()),('01K1000000002','01K0000000041','01K0000000031',2,'서연: 결제부터요. PayGuard 재시도는 현재 한 번이고 실패율이 2.8%입니다.',12000,20000,now(),now()),('01K1000000003','01K0000000041','01K0000000031',3,'도윤: 재시도를 늘리면 중복 승인 위험은 누가 막죠?',24000,32000,now(),now()),('01K1000000004','01K0000000041','01K0000000031',4,'하나: idempotency key는 주문 단위로 이미 들어가 있습니다.',36000,44000,now(),now()),('01K1000000005','01K0000000041','01K0000000031',5,'민수: 결론은 아직 내리지 말고 근거부터 보죠.',48000,56000,now(),now()),('01K1000000006','01K0000000041','01K0000000031',6,'서연: 두 번째 시도를 800ms 뒤에 넣으면 복구율이 61%까지 올라갑니다.',60000,68000,now(),now()),('01K1000000007','01K0000000041','01K0000000031',7,'도윤: PG 장애 때 요청을 더 보내는 셈이라 circuit breaker 조건이 필요합니다.',72000,80000,now(),now()),('01K1000000008','01K0000000041','01K0000000031',8,'하나: 그건 제가 staging 로그로 확인해볼게요.',84000,92000,now(),now()),('01K1000000009','01K0000000041','01K0000000031',9,'민수: 검색도 잠깐 보죠. 어제 P95가 920ms였습니다.',96000,104000,now(),now()),('01K1000000010','01K0000000041','01K0000000031',10,'하나: 잠깐만요, 주말 캠핑 사진 알림이 계속 뜨네요. 회의 뒤에 끄겠습니다.',108000,116000,now(),now()),('01K1000000011','01K0000000041','01K0000000031',11,'서연: Redis에 인기 질의 결과를 60초 cache하면 목표 500ms 아래로 갑니다.',120000,128000,now(),now()),('01K1000000012','01K0000000041','01K0000000031',12,'도윤: 가격 변경이 60초 늦게 보이면 CS가 생기지 않나요?',132000,140000,now(),now()),('01K1000000013','01K0000000041','01K0000000031',13,'하나: 가격 필드는 cache에서 빼고 상품 ID 목록만 저장할 수 있습니다.',144000,152000,now(),now()),('01K1000000014','01K0000000041','01K0000000031',14,'민수: 좋습니다. 다시 결제로 돌아가죠.',156000,164000,now(),now()),('01K1000000015','01K0000000041','01K0000000031',15,'서연: PayGuard는 네트워크 timeout만 재시도하고 거절 응답은 그대로 종료하겠습니다.',168000,176000,now(),now()),('01K1000000016','01K0000000041','01K0000000031',16,'도윤: timeout 판별이 ''타임 아웃트''로 잘못 찍힌 로그도 있던데 코드값을 쓰나요?',180000,188000,now(),now()),('01K1000000017','01K0000000041','01K0000000031',17,'하나: 네, 문자열이 아니라 PG 코드 91만 봅니다.',192000,200000,now(),now()),('01K1000000018','01K0000000041','01K0000000031',18,'민수: 그 조건이면 재시도 두 번 제안은 어떤가요?',204000,212000,now(),now()),('01K1000000019','01K0000000041','01K0000000031',19,'도윤: 두 번은 peak 때 부하가 큽니다. 우선 한 번 추가가 낫습니다.',216000,224000,now(),now()),('01K1000000020','01K0000000041','01K0000000031',20,'서연: 한 번 추가로도 복구율 61% 수치가 나온 겁니다.',228000,236000,now(),now()),('01K1000000021','01K0000000041','01K0000000031',21,'민수: 그럼 추가 재시도는 한 번으로 조건부 합의합니다.',240000,248000,now(),now()),('01K1000000022','01K0000000041','01K0000000031',22,'하나: 네.',252000,260000,now(),now()),('01K1000000023','01K0000000041','01K0000000031',23,'민수: 검색 안건으로 넘어갑니다.',264000,272000,now(),now()),('01K1000000024','01K0000000041','01K0000000031',24,'서연: Redis TTL은 아까 60초라 했지만 가격을 제외하면 120초도 가능합니다.',276000,284000,now(),now()),('01K1000000025','01K0000000041','01K0000000031',25,'도윤: 재고 품절 반영은요? 상품 ID가 남으면 품절 상품이 노출됩니다.',288000,296000,now(),now()),('01K1000000026','01K0000000041','01K0000000031',26,'하나: 검색 응답 조립 때 재고 API를 다시 봅니다. 다만 그 API가 느리면...',300000,308000,now(),now()),('01K1000000027','01K0000000041','01K0000000031',27,'민수: 끊겼네요. 다시 말씀해 주세요.',312000,320000,now(),now()),('01K1000000028','01K0000000041','01K0000000031',28,'하나: 재고 API 실패 시 cache 결과를 쓰지 않고 기존 검색으로 fallback합니다.',324000,332000,now(),now()),('01K1000000029','01K0000000041','01K0000000031',29,'서연: 그러면 Redis 장애도 동일하게 fallback하면 됩니다.',336000,344000,now(),now()),('01K1000000030','01K0000000041','01K0000000031',30,'도윤: cache miss 폭주, 이른바 thundering herd는 막아야 합니다.',348000,356000,now(),now()),('01K1000000031','01K0000000041','01K0000000031',31,'서연: 키별 lock까지 넣으면 일정이 늘어요. TTL jitter 10%면 충분합니다.',360000,368000,now(),now()),('01K1000000032','01K0000000041','01K0000000031',32,'민수: 목표가 이번 출시라서 TTL jitter로 한정하죠.',372000,380000,now(),now()),('01K1000000033','01K0000000041','01K0000000031',33,'하나: Redis 설정과 fallback QA는 제가 목요일까지 확인하겠습니다.',384000,392000,now(),now()),('01K1000000034','01K0000000041','01K0000000031',34,'민수: 목요일까지요?',396000,404000,now(),now()),('01K1000000035','01K0000000041','01K0000000031',35,'하나: 아, 목요일이 공휴일이라 금요일 오전 10시까지로 바꾸겠습니다.',408000,416000,now(),now()),('01K1000000036','01K0000000041','01K0000000031',36,'도윤: 금요일 deploy 전에 한 시간밖에 없는데요.',420000,428000,now(),now()),('01K1000000037','01K0000000041','01K0000000031',37,'서연: deploy를 오후 3시로 미루면 검증 시간이 생깁니다.',432000,440000,now(),now()),('01K1000000038','01K0000000041','01K0000000031',38,'민수: 배포 안건을 지금 같이 엽니다. 원래 오후 1시였죠.',444000,452000,now(),now()),('01K1000000039','01K0000000041','01K0000000031',39,'하나: 네, runbook에는 1시로 적혀 있습니다.',456000,464000,now(),now()),('01K1000000040','01K0000000041','01K0000000031',40,'도윤: 금요일 3시는 장애 대응 시간이 짧습니다. rollback 기준부터 정하죠.',468000,476000,now(),now()),('01K1000000041','01K0000000041','01K0000000031',41,'서연: 결제 실패율 4% 또는 검색 P95 1초 초과가 10분 지속되면 rollback 어떨까요?',480000,488000,now(),now()),('01K1000000042','01K0000000041','01K0000000031',42,'민수: 10분은 길다는 의견 있나요?',492000,500000,now(),now()),('01K1000000043','01K0000000041','01K0000000031',43,'도윤: 결제는 5분, 검색은 10분으로 나눠야 합니다.',504000,512000,now(),now()),('01K1000000044','01K0000000041','01K0000000031',44,'하나: monitor alert도 두 개로 나눌 수 있습니다.',516000,524000,now(),now()),('01K1000000045','01K0000000041','01K0000000031',45,'민수: 좋습니다. 그 기준으로 갑니다.',528000,536000,now(),now()),('01K1000000046','01K0000000041','01K0000000031',46,'서연: 아 아까 Redis TTL요. 120초 대신 90초가 운영팀 승인받기 쉽습니다.',540000,548000,now(),now()),('01K1000000047','01K0000000041','01K0000000031',47,'도윤: 숫자를 바꾸는 근거가 승인 편의뿐이면 안 됩니다.',552000,560000,now(),now()),('01K1000000048','01K0000000041','01K0000000031',48,'서연: 지난주 로그로 90초 내 재고 상태 변경은 0.3%였고 조립 단계에서 걸러집니다.',564000,572000,now(),now()),('01K1000000049','01K0000000041','01K0000000031',49,'도윤: 그 근거라면 90초에 동의합니다.',576000,584000,now(),now()),('01K1000000050','01K0000000041','01K0000000031',50,'민수: Redis TTL 90초, jitter 10%, 재고 API 실패 시 기존 검색 fallback으로 정리합니다.',588000,596000,now(),now()),('01K1000000051','01K0000000041','01K0000000031',51,'하나: 설정 PR은 제가 오늘 오후에 올리겠습니다.',600000,608000,now(),now()),('01K1000000052','01K0000000041','01K0000000031',52,'민수: 담당과 기한 명확합니다.',612000,620000,now(),now()),('01K1000000053','01K0000000041','01K0000000031',53,'서연: 결제 쪽 feature flag 이름은 payguard_retry_v2로 제안합니다.',624000,632000,now(),now()),('01K1000000054','01K0000000041','01K0000000031',54,'도윤: v2가 뭘 뜻하는지 모호합니다. payguard_timeout_retry가 낫죠.',636000,644000,now(),now()),('01K1000000055','01K0000000041','01K0000000031',55,'하나: 기존 flag 길이 제한이 서른두 자라 그 이름도 들어갑니다.',648000,656000,now(),now()),('01K1000000056','01K0000000041','01K0000000031',56,'민수: 그럼 payguard_timeout_retry로 하죠.',660000,668000,now(),now()),('01K1000000057','01K0000000041','01K0000000031',57,'서연: 제가 flag 생성과 대시보드 지표 연결을 수요일까지 맡겠습니다.',672000,680000,now(),now()),('01K1000000058','01K0000000041','01K0000000031',58,'도윤: 대시보드에서 중복 승인 건수도 보여야 합니다.',684000,692000,now(),now()),('01K1000000059','01K0000000041','01K0000000031',59,'서연: 네, duplicate_authorization 지표를 같이 넣겠습니다.',696000,704000,now(),now()),('01K1000000060','01K0000000041','01K0000000031',60,'민수: 배포 전 QA 범위를 확인합시다.',708000,716000,now(),now()),('01K1000000061','01K0000000041','01K0000000031',61,'하나: 정상 승인, timeout 후 성공, timeout 후 최종 실패, 거절 무재시도 네 경로입니다.',720000,728000,now(),now()),('01K1000000062','01K0000000041','01K0000000031',62,'도윤: 사용자 취소 직후 늦은 승인 경로가 빠졌습니다.',732000,740000,now(),now()),('01K1000000063','01K0000000041','01K0000000031',63,'하나: 맞아요. 다섯 번째로 추가하겠습니다.',744000,752000,now(),now()),('01K1000000064','01K0000000041','01K0000000031',64,'서연: 그 경로는 sandbox에서 지연 응답을 만들 수 있나요?',756000,764000,now(),now()),('01K1000000065','01K0000000041','01K0000000031',65,'하나: mock PG로 3초 delay를 주면 됩니다.',768000,776000,now(),now()),('01K1000000066','01K0000000041','01K0000000031',66,'민수: 하나님이 다섯 경로 QA를 금요일 오전 10시까지 완료하는 걸로요.',780000,788000,now(),now()),('01K1000000067','01K0000000041','01K0000000031',67,'하나: 네, 결과를 PR에 붙이겠습니다.',792000,800000,now(),now()),('01K1000000068','01K0000000041','01K0000000031',68,'도윤: 아까 deploy 오후 3시가 최종인가요?',804000,812000,now(),now()),('01K1000000069','01K0000000041','01K0000000031',69,'민수: 아직 rollback 담당을 정하지 않았습니다.',816000,824000,now(),now()),('01K1000000070','01K0000000041','01K0000000031',70,'서연: 배포는 제가 할 수 있지만 결제 지표도 동시에 봐야 합니다.',828000,836000,now(),now()),('01K1000000071','01K0000000041','01K0000000031',71,'도윤: 제가 배포 후 30분 동안 결제와 검색 alert를 보겠습니다.',840000,848000,now(),now()),('01K1000000072','01K0000000041','01K0000000031',72,'민수: 좋습니다. rollback 실행은 누가 하죠?',852000,860000,now(),now()),('01K1000000073','01K0000000041','01K0000000031',73,'하나: 제가 console 권한이 없어서 못 합니다.',864000,872000,now(),now()),('01K1000000074','01K0000000041','01K0000000031',74,'서연: rollback 실행은 제가 맡겠습니다. 기준 충족 시 민수님 승인 기다리지 않고 진행하죠.',876000,884000,now(),now()),('01K1000000075','01K0000000041','01K0000000031',75,'민수: 네, 고객 영향 기준이니 즉시 rollback으로 합의합니다.',888000,896000,now(),now()),('01K1000000076','01K0000000041','01K0000000031',76,'도윤: 단, 지표 수집 자체가 끊기면요?',900000,908000,now(),now()),('01K1000000077','01K0000000041','01K0000000031',77,'서연: 그 경우 신규 버전 health check 실패로 보고 rollback하겠습니다.',912000,920000,now(),now()),('01K1000000078','01K0000000041','01K0000000031',78,'민수: 배포는 금요일 오후 3시, 모니터링 30분입니다.',924000,932000,now(),now()),('01K1000000079','01K0000000041','01K0000000031',79,'하나: 검색 load test는 아직 안 정했습니다.',936000,944000,now(),now()),('01K1000000080','01K0000000041','01K0000000031',80,'서연: 동시 300 요청으로 15분이면 충분합니다.',948000,956000,now(),now()),('01K1000000081','01K0000000041','01K0000000031',81,'도윤: 평소 peak가 420인데 300은 낮습니다.',960000,968000,now(),now()),('01K1000000082','01K0000000041','01K0000000031',82,'서연: 그럼 500 요청으로 20분 돌리겠습니다. P95 500ms 목표입니다.',972000,980000,now(),now()),('01K1000000083','01K0000000041','01K0000000031',83,'하나: 제가 목요일... 아니 금요일 오전에 QA와 같이 돌리면 시간이 부족합니다.',984000,992000,now(),now()),('01K1000000084','01K0000000041','01K0000000031',84,'민수: load test는 서연님이 목요일 전날, 수요일 오후까지 맡아주세요.',996000,1004000,now(),now()),('01K1000000085','01K0000000041','01K0000000031',85,'서연: 네, 수요일 오후 6시까지 결과 공유하겠습니다.',1008000,1016000,now(),now()),('01K1000000086','01K0000000041','01K0000000031',86,'도윤: 공휴일 전날 트래픽 패턴이 달라서 production replay 비율도 적어주세요.',1020000,1028000,now(),now()),('01K1000000087','01K0000000041','01K0000000031',87,'서연: 민감 필드는 제거한 질의 ID만 replay하겠습니다.',1032000,1040000,now(),now()),('01K1000000088','01K0000000041','01K0000000031',88,'민수: 좋습니다. 개인정보 없는 데이터만 사용합니다.',1044000,1052000,now(),now()),('01K1000000089','01K0000000041','01K0000000031',89,'하나: 아 아까 결제 재시도 간격 800ms가 모바일 timeout과 겹치지 않나요?',1056000,1064000,now(),now()),('01K1000000090','01K0000000041','01K0000000031',90,'서연: 클라이언트 전체 timeout은 5초라 800ms 한 번은 들어갑니다.',1068000,1076000,now(),now()),('01K1000000091','01K0000000041','01K0000000031',91,'도윤: 네트워크가 느리면 첫 요청 판정에 이미 4초가 걸릴 수 있습니다.',1080000,1088000,now(),now()),('01K1000000092','01K0000000041','01K0000000031',92,'하나: PG 코드 91은 2초 안에 오니 해당 코드일 때만 재시도합니다.',1092000,1100000,now(),now()),('01K1000000093','01K0000000041','01K0000000031',93,'민수: 그러면 800ms 한 번, 코드 91 한정으로 확정합니다.',1104000,1112000,now(),now()),('01K1000000094','01K0000000041','01K0000000031',94,'서연: 문서에는 ''재시도 최대 1회''라고 쓰겠습니다.',1116000,1124000,now(),now()),('01K1000000095','01K0000000041','01K0000000031',95,'도윤: ''최대''가 초기 요청 포함인지 헷갈립니다. 추가 1회라고 쓰죠.',1128000,1136000,now(),now()),('01K1000000096','01K0000000041','01K0000000031',96,'서연: 동의합니다.',1140000,1148000,now(),now()),('01K1000000097','01K0000000041','01K0000000031',97,'민수: 후반 정리 들어갑니다. PayGuard는 코드 91에 800ms 뒤 추가 1회입니다.',1152000,1160000,now(),now()),('01K1000000098','01K0000000041','01K0000000031',98,'민수: 검색은 Redis TTL 90초, jitter 10%, 재고 API 실패 시 기존 검색 fallback입니다.',1164000,1172000,now(),now()),('01K1000000099','01K0000000041','01K0000000031',99,'민수: deploy는 금요일 오후 3시, 결제 4% 5분 또는 검색 P95 1초 10분이면 rollback입니다.',1176000,1184000,now(),now()),('01K1000000100','01K0000000041','01K0000000031',100,'하나: QA 다섯 경로 결과는 금요일 오전 10시까지 PR에 첨부합니다.',1188000,1196000,now(),now()),('01K1000000101','01K0000000041','01K0000000031',101,'서연: 제가 수요일 6시까지 500 동시 요청 load test, flag와 지표 연결도 수요일까지 하겠습니다.',1200000,1208000,now(),now()),('01K1000000102','01K0000000041','01K0000000031',102,'도윤: 저는 배포 후 30분 모니터링합니다.',1212000,1220000,now(),now()),('01K1000000103','01K0000000041','01K0000000031',103,'서연: rollback 실행은 제가 맡습니다.',1224000,1232000,now(),now()),('01K1000000104','01K0000000041','01K0000000031',104,'민수: 빠진 안건 있나요?',1236000,1244000,now(),now()),('01K1000000105','01K0000000041','01K0000000031',105,'도윤: Redis 비용 상한만요. 월 20만 원을 넘으면 다음 회의에서 재검토합시다.',1248000,1256000,now(),now()),('01K1000000106','01K0000000041','01K0000000031',106,'민수: 운영 관찰 조건으로 남기되 이번 deploy 차단 조건은 아닙니다.',1260000,1268000,now(),now()),('01K1000000107','01K0000000041','01K0000000031',107,'하나: 네.',1272000,1280000,now(),now()),('01K1000000108','01K0000000041','01K0000000031',108,'민수: 세 안건 모두 닫겠습니다.',1284000,1292000,now(),now())
ON CONFLICT (id) DO NOTHING;
